import{_ as s,c as a,o as e,ag as t}from"./chunks/framework.ymCRTBvy.js";const c=JSON.parse('{"title":"9.4_实现沿着路径移动的动画","description":"","frontmatter":{},"headers":[],"relativePath":"swift/uikit/uikit_animation/9.4_实现沿着路径移动的动画.md","filePath":"swift/uikit/uikit_animation/9.4_实现沿着路径移动的动画.md"}'),n={name:"swift/uikit/uikit_animation/9.4_实现沿着路径移动的动画.md"};function l(h,i,o,d,r,k){return e(),a("div",null,i[0]||(i[0]=[t(`<h1 id="_9-4-实现沿着路径移动的动画" tabindex="-1">9.4_实现沿着路径移动的动画 <a class="header-anchor" href="#_9-4-实现沿着路径移动的动画" aria-label="Permalink to &quot;9.4_实现沿着路径移动的动画&quot;">​</a></h1><h2 id="路径动画的魅力-✨" tabindex="-1">路径动画的魅力 ✨ <a class="header-anchor" href="#路径动画的魅力-✨" aria-label="Permalink to &quot;路径动画的魅力 ✨&quot;">​</a></h2><p>路径动画是iOS动画中一个非常引人入胜的特性，它允许你让视图沿着预定义的路径移动，而不是简单的直线运动。这为你的应用带来了无限的创意可能性，让用户界面更加生动有趣。想象一下，一个图标沿着一个心形路径跳动，或者一个元素沿着一个复杂的曲线优雅地滑过屏幕，这些都能极大地提升用户体验！</p><h2 id="定义运动路径-🛣️" tabindex="-1">定义运动路径 🛣️ <a class="header-anchor" href="#定义运动路径-🛣️" aria-label="Permalink to &quot;定义运动路径 🛣️&quot;">​</a></h2><p>要实现沿着路径移动的动画，核心在于定义这个“路径”。在Core Animation中，我们通常使用<code>UIBezierPath</code>来创建这些路径。<code>UIBezierPath</code>是一个强大的工具，可以绘制直线、曲线、矩形、圆形等各种形状。你可以通过以下几种方式来定义路径：</p><ul><li><strong>直线路径</strong>: 使用<code>addLine(to:)</code>方法连接多个点。</li><li><strong>曲线路径</strong>: 使用<code>addCurve(to:controlPoint1:controlPoint2:)</code>或<code>addQuadCurve(to:controlPoint:)</code>创建贝塞尔曲线。</li><li><strong>预设形状</strong>: <code>UIBezierPath</code>也提供了方便的初始化方法来创建矩形、圆形或椭圆路径。</li></ul><p>例如，你可以创建一个简单的圆形路径：</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> circlePath </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> UIBezierPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">arcCenter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CGPoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">y</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">radius</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">startAngle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">endAngle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: CGFloat.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">clockwise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="结合cakeyframeanimation-🔑" tabindex="-1">结合CAKeyframeAnimation 🔑 <a class="header-anchor" href="#结合cakeyframeanimation-🔑" aria-label="Permalink to &quot;结合CAKeyframeAnimation 🔑&quot;">​</a></h2><p>一旦你定义了路径，就可以将其与<code>CAKeyframeAnimation</code>结合起来。<code>CAKeyframeAnimation</code>是实现路径动画的关键。它允许你指定动画在关键帧之间如何变化，而路径动画正是利用了它的<code>path</code>属性。</p><ol><li><strong>创建<code>CAKeyframeAnimation</code>实例</strong>: 首先，你需要创建一个<code>CAKeyframeAnimation</code>对象。</li><li><strong>设置<code>keyPath</code></strong>: 将<code>keyPath</code>设置为<code>&quot;position&quot;</code>，因为我们希望动画改变视图的位置。</li><li><strong>指定<code>path</code></strong>: 将你创建的<code>UIBezierPath</code>的<code>cgPath</code>属性赋值给动画的<code>path</code>属性。</li></ol><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> animation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CAKeyframeAnimation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keyPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;position&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation.path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> circlePath.cgPath</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="动画属性的精细控制-⚙️" tabindex="-1">动画属性的精细控制 ⚙️ <a class="header-anchor" href="#动画属性的精细控制-⚙️" aria-label="Permalink to &quot;动画属性的精细控制 ⚙️&quot;">​</a></h2><p>除了路径本身，你还可以对路径动画进行更精细的控制，以达到你想要的效果。</p><ul><li><strong><code>duration</code></strong>: 设置动画的持续时间，例如<code>animation.duration = 3.0</code>表示动画将在3秒内完成。</li><li><strong><code>repeatCount</code></strong>: 控制动画重复的次数，设置为<code>.infinity</code>可以实现无限循环。</li><li><strong><code>calculationMode</code></strong>: 这个属性非常重要，它决定了动画在路径上的插值方式。 <ul><li><code>.linear</code>: 匀速运动。</li><li><code>.paced</code>: 动画会尝试保持恒定的速度，即使路径的长度不均匀。这是路径动画的常用选项。</li></ul></li><li><strong><code>rotationMode</code></strong>: 如果你希望视图在沿着路径移动时自动旋转以匹配路径的方向，可以设置<code>rotationMode</code>为<code>kCAAnimationRotateAuto</code>。</li></ul><h2 id="将动画添加到图层-🚀" tabindex="-1">将动画添加到图层 🚀 <a class="header-anchor" href="#将动画添加到图层-🚀" aria-label="Permalink to &quot;将动画添加到图层 🚀&quot;">​</a></h2><p>最后一步是将配置好的<code>CAKeyframeAnimation</code>添加到你想要动画的<code>CALayer</code>上。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">yourView.layer.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(animation, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">forKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pathAnimation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>通过这些步骤，你的视图就会沿着你定义的路径优雅地移动了！这种能力让你能够创造出真正令人惊叹的用户体验，让你的应用在众多应用中脱颖而出。快去尝试一下，发挥你的创意吧！🎨</p>`,19)]))}const E=s(n,[["render",l]]);export{c as __pageData,E as default};
